package controller;import java.util.List;
public final class Level1Controller extends BaseLevelController{protected int level(){return 1;}protected String titleText(){return "THE WATER MOLECULE";}protected String objectiveText(){return "Build H₂O and recognise its polar, bent structure.";}protected String instructionText(){return "Select the atoms in molecular order: hydrogen → oxygen → hydrogen.";}protected List<String> challengeItems(){return List.of("H  Hydrogen","O  Oxygen","H  Hydrogen");}protected List<Integer> correctOrder(){return List.of(0,1,2);}protected String quizPrompt(){return "What is the H–O–H bond angle?";}protected List<String> quizChoices(){return List.of("90°","104.5°","120°","180°");}protected int quizCorrect(){return 1;}protected String explanation(){return "Electron-pair repulsion gives water its characteristic 104.5° bent shape.";}}
